src/components/pages/landingPage/section:
'use client'

import * as React from 'react';
import Image from "next/image";

import aboutProfileImage from '@/assets/images/about-profile-crop.jpg';
import {ChevronRight} from "lucide-react";
import {buttonVariants} from "../../../ui/button";
import Link from "next/link";
import { ABOUT_EDUCATION_INFO, ABOUT_INFO_1, ABOUT_INFO_2, ABOUT_INFO_3, ABOUT_PERSONAL_INFO } from '@/components/constants/about';


const About = () => {
    return (
        <div id="about" className="min-h-screen w-full flex flex-col items-center pt-12">
            <div className="text-center relative flex flex-col items-center relative w-[90%] md:w-[60%]">
                <p className="!font-raleway text-[#45505b] text-[32px] font-bold pb-4">About</p>
                <span className="border-b border-b-solid border-b-black w-[200px]">{}</span>
                <span className="border-b border-b-solid border-b-[#0563bb] w-[100px]">{}</span>
                <p className="lead py-4 !font-raleway">{ABOUT_INFO_1}</p>

                <div className="grid grid-cols-1 md:grid-cols-8 gap-0 md:gap-8 py-4">
                    <div className="col-span-3 flex flex-col justify-center w-full">
                        <Image src={aboutProfileImage} className="w-full h-full object-contain"
                               alt="about-profile" />
                    </div>
                    <div className="col-span-5 flex flex-col">
                        <p className="lead text-center md:text-left text-[24px] font-bold !font-raleway text-[#45505b] py-8 md:py-0">
                            Fullstack Developer / AI Engineer
                        </p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-8 py-8 h-full">
                            {Object.values(ABOUT_PERSONAL_INFO).map(row =>
                                <div className="flex flex-row items-center gap-x-0">
                                    <ChevronRight className="text-[#0563bb] size-[25px]" />
                                    <p className="text-md lead font-bold !font-raleway">{row.label}:</p>
                                    {row.url !== "" ?
                                        <p className="text-md lead !font-raleway pl-2">
                                            <Link href={row.url} className={buttonVariants({ variant: "ghost" })}>
                                                {row.value}
                                            </Link>
                                        </p>:
                                        <p className="text-md lead !font-raleway pl-2">{row.value}</p> 
                                    }
                                </div>
                            )}
                        </div>
                        <p className="lead pt-2 text-center md:text-left !font-raleway text-balance">{ABOUT_INFO_2}</p>
                    </div>
                </div>

                <p className="lead py-6 text-center md:text-left !font-raleway text-balance">{ABOUT_INFO_3}</p>
            </div>
            
            <div className="w-full flex flex-col items-center pt-12 pb-16 bg-gray-50/30">
            {/* Header Section */}
            <div className="text-center flex flex-col items-center w-[90%] md:w-[75%] max-w-6xl mb-10">
                <h2 className="!font-raleway text-[#45505b] text-[32px] font-bold pb-2">Education</h2>
                <span className="border-b border-b-solid border-b-gray-300 w-[160px]"></span>
                <span className="border-b-2 border-b-solid border-b-[#0563bb] w-[80px] mb-8"></span>
            </div>

            {/* Education Content Card */}
            <div className="w-[90%] md:w-[60%] p-6 md:p-8 shadow-md rounded-xl bg-white border border-gray-100 text-left relative overflow-hidden hover:shadow-lg transition-all duration-300">
                
                {/* Left decorative brand accent line */}
                <div className="absolute left-0 top-0 bottom-0 w-[4px] bg-[#0563bb]" />
                
                <div className="flex flex-col gap-y-3 pl-2">
                    {/* Institution and Date Badge */}
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-y-2">
                        <h3 className="text-lg font-bold text-gray-700 tracking-wide">
                            {ABOUT_EDUCATION_INFO.INSTITUTION}
                        </h3>
                        <span className="self-start sm:self-auto text-xs font-bold text-[#0563bb] bg-blue-50/80 border border-blue-100 px-3 py-1 rounded-full uppercase tracking-wider whitespace-nowrap">
                            {ABOUT_EDUCATION_INFO.DATE}
                        </span>
                    </div>

                    {/* Degree Title */}
                    <h4 className="text-md font-semibold text-[#0563bb] !font-raleway">
                        {ABOUT_EDUCATION_INFO.DEGREE}
                    </h4>

                    {/* Description Paragraph */}
                    <p className="text-sm md:text-base text-gray-500 leading-relaxed font-normal mt-1">
                        {ABOUT_EDUCATION_INFO.DESCRIPTION}
                    </p>
                </div>
            </div>
        </div>
        </div>
    );
}

export default About;

'use client'

import * as React from 'react';
import { Award, ExternalLink, Calendar, ShieldCheck } from "lucide-react";
import { CERTFICATES_INFO } from '@/components/constants/certificates';


const Certificates = () => {
    // Convert object properties into a dynamic array
    const certificatesList = Object.values(CERTFICATES_INFO);

    return (
        <div id="certificates" className="min-h-screen w-full flex flex-col items-center pt-12 bg-white selection:bg-blue-100">
            <div className="relative flex flex-col items-center w-[85%] md:w-[60%] text-center">
                <p className="!font-raleway text-[#45505b] text-[32px] font-bold pb-4">Certifications</p>
                <span className="border-b border-b-solid border-b-black w-[200px]"></span>
                <span className="border-b border-b-solid border-b-[#0563bb] w-[100px] -mt-[1px]"></span>
                
                <div className="w-full py-12">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-left">
                        {certificatesList.map((cert, index) => {
                            // Normalize displaying continuous vs expiring certificates cleanly
                            const displayDate = cert.issued.replace(" - *", " (No Expiration)");

                            return (
                                <div 
                                    key={index} 
                                    className="flex flex-col justify-between p-6 rounded-xl border border-gray-100 bg-white shadow-sm hover:shadow-md transition-shadow duration-300 group"
                                >
                                    <div>
                                        {/* Header Row */}
                                        <div className="flex items-start justify-between gap-x-4 mb-3">
                                            <div className="rounded-lg bg-blue-50 text-[#0563bb] p-2.5 shrink-0 group-hover:bg-[#0563bb] group-hover:text-white transition-colors duration-300">
                                                {cert.name.includes("Security") ? (
                                                    <ShieldCheck className="size-5" />
                                                ) : (
                                                    <Award className="size-5" />
                                                )}
                                            </div>
                                            <a 
                                                href={cert.badge} 
                                                target="_blank" 
                                                rel="noopener noreferrer" 
                                                className="text-gray-400 hover:text-[#0563bb] p-1 rounded-md transition-colors"
                                                title="Verify Credential"
                                            >
                                                <ExternalLink className="size-4" />
                                            </a>
                                        </div>

                                        {/* Certification Name */}
                                        <h3 className="text-base font-bold !font-raleway text-[#45505b] line-clamp-2 leading-snug mb-1">
                                            {cert.name}
                                        </h3>
                                        
                                        {/* Organization Issuer */}
                                        <p className="text-sm font-semibold text-[#0563bb] !font-raleway uppercase tracking-wider text-[11px] mb-4">
                                            {cert.organization}
                                        </p>
                                    </div>

                                    {/* Footer Meta Details */}
                                    <div className="mt-4 pt-3 border-t border-gray-50 flex flex-col gap-y-1.5 text-xs text-gray-500 !font-raleway">
                                        <div className="flex items-center gap-x-2">
                                            <Calendar className="size-3.5 text-gray-400 shrink-0" />
                                            <span>{displayDate}</span>
                                        </div>
                                        <div className="flex flex-col gap-y-0.5 mt-1">
                                            <span className="text-[10px] font-medium text-gray-400 uppercase tracking-tight">Credential ID</span>
                                            <span className="font-mono text-[11px] text-gray-600 truncate max-w-full" title={cert.credentialID}>
                                                {cert.credentialID}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Certificates;

'use client'

import * as React from 'react';
import { BriefcaseBusiness, Circle } from "lucide-react";
import { EXPERIENCE_INFO } from '@/components/constants/experiences';

const Resume = () => {
  return (
    <div id="resume" className="min-h-screen w-full flex flex-col items-center pt-12 bg-white selection:bg-blue-100">
      <div className="relative flex flex-col items-center w-[85%] md:w-[60%] text-center">
        <p className="!font-raleway text-[#45505b] text-[32px] font-bold pb-4">Resume</p>
        <span className="border-b border-b-solid border-b-black w-[200px]"></span>
        <span className="border-b border-b-solid border-b-[#0563bb] w-[100px] -mt-[1px]"></span>
        
        <div className="w-full py-12 flex flex-col">
          <p className="text-2xl font-bold !font-raleway text-[#45505b] mb-12 text-left md:text-center">
            Professional Experience
          </p>
          
          <div className="flex flex-col gap-y-12">
            {Object.values(EXPERIENCE_INFO).map((job, idx) => (
              <div key={idx} className="grid grid-cols-1 md:grid-cols-12 gap-4 md:gap-8 py-4 border-b border-gray-100 pb-8 last:border-0">
                {/* Left Side: Role Title & Dates */}
                <div className="md:col-span-4 flex flex-row justify-between md:justify-end gap-x-4 text-left md:text-right">
                  <div className="flex flex-col md:items-end">
                    <p className="text-md font-semibold !font-raleway text-[#45505b]">
                      {job.position}
                    </p>
                    <p className="text-sm font-light !font-raleway text-gray-500 mt-1">
                      {job.range}
                    </p>
                  </div>
                  {/* Icon Timeline Container */}
                  <div className="hidden md:flex flex-col items-center">
                    <div className="rounded-full bg-[#0563bb] size-[40px] flex justify-center items-center shrink-0 shadow-sm">
                      <BriefcaseBusiness className="text-white size-4" />
                    </div>
                  </div>
                </div>

                {/* Right Side: Company Details & Breakdown */}
                <div className="md:col-span-8 flex flex-col gap-y-4 text-left">
                  <div className="flex flex-col justify-center gap-y-2">
                    <p className="text-md font-bold uppercase tracking-wider !font-raleway text-[#0563bb]">
                      {job.company}
                    </p>
                    <span className="border-b-[3px] border-solid border-b-gray-300 w-[40px]"></span>
                  </div>
                  
                  {/* Responsibilities list */}
                  <div className="flex flex-col gap-y-3 pt-2">
                    {job.responsibilities.map((resp, respIdx) => (
                      <div key={respIdx} className="flex flex-row items-start gap-x-3 group">
                        <Circle className="size-[6px] fill-gray-400 text-gray-400 mt-[7px] shrink-0 group-hover:fill-[#0563bb] group-hover:text-[#0563bb] transition-colors" />
                        <p className="text-sm md:text-sm !font-raleway text-[#45505b] leading-relaxed text-justify">
                          {resp}
                        </p>
                      </div>
                    ))}
                  </div>

                  {/* Projects Highlight Row */}
                  {job.projects.length > 0 && (
                    <div className="mt-4 pt-3 border-t border-dashed border-gray-200">
                      <p className="text-xs font-semibold uppercase tracking-wider text-gray-400 mb-2 !font-raleway">
                        Featured Projects
                      </p>
                      <div className="flex flex-wrap gap-2">
                        {job.projects.map((project, pIdx) => (
                          <span 
                            key={pIdx} 
                            className="bg-gray-100 text-gray-700 text-xs px-2.5 py-1 rounded-md font-medium !font-raleway border border-gray-200/60"
                          >
                            {project}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Resume;

