'use client'

import * as React from 'react';

const LOOM_EMBED_ID = "114326a402804744816b20a190b19b93";

const VideoIntro = () => {
    const sectionRef = React.useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = React.useState(false);

    React.useEffect(() => {
        const section = sectionRef.current;
        if (!section) return;

        const observer = new IntersectionObserver(
            ([entry]) => {
                setIsVisible(entry.isIntersecting);
            },
            { threshold: 0.5 }
        );

        observer.observe(section);
        return () => observer.disconnect();
    }, []);

    return (
        <div id="video-intro" ref={sectionRef} className="min-h-screen w-full flex flex-col items-center justify-center pt-12">
            <div className="text-center relative flex flex-col items-center w-[90%] md:w-[60%]">
