'use client'

import * as React from 'react';
import { House, UserRound, Code2, FolderKanban, FileText, ScrollText, Video } from "lucide-react";

import { Button } from '@/components/ui/button';

const NAV_ITEMS = [
  { id: 'hero', label: 'Home', Icon: House },
  { id: 'video-intro', label: 'Video Intro', Icon: Video },
  { id: 'about', label: 'About', Icon: UserRound },
  { id: 'skills', label: 'Skills', Icon: Code2 },
  { id: 'projects', label: 'Projects', Icon: FolderKanban },
  { id: 'resume', label: 'Resume', Icon: FileText },
  { id: 'certificates', label: 'Certificates', Icon: ScrollText },
] as const;

const NavbarItems = ({ onItemClick }: { onItemClick?: () => void }) => {
  const [activeSection, setActiveSection] = React.useState('hero');

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        }
      },
      { rootMargin: '-50% 0px -50% 0px' }
    );

    for (const { id } of NAV_ITEMS) {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    }

    return () => observer.disconnect();
  }, []);

  const scrollTo = (id: string) => {
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
      onItemClick?.();
    }
  };

  return (
    <div className="w-full min-h-[100px] flex flex-col justify-center pl-6 gap-y-2">
      {NAV_ITEMS.map(({ id, label, Icon }) => {
        const isActive = activeSection === id;
        return (
          <Button
            key={id}
            variant="outline"
            onClick={() => scrollTo(id)}
            className={`group rounded-full h-[55px] w-[120px] border-[#0563bb] 
                        md:size-[55px] hover:h-[55px] hover:w-[120px] hover:bg-[#0563bb]
                        cursor-pointer duration-700 flex flex-row ${isActive ? "bg-[#0563bb]" : ""}`}
          >
            <Icon className={`size-[20px] group-hover:text-white transition-colors duration-500 ${isActive ? "text-white active" : "text-[#45505b]"}`} />
            <span className={`block text-center transition-all duration-500
                             md:hidden md:group-hover:block ${isActive ? "text-white active" : "text-[#45505b]"}`}>{label}</span>
          </Button>
        );
      })}
    </div>
  );
}

export default NavbarItems;

